// Producer: publishes an event without waiting for it to be processed
await queue.publish('order.created', { orderId: 42, amount: 4500 });
console.log('Order recorded, processing in the background');

// Consumer: processes messages at its own pace
queue.subscribe('order.created', async (message) => {
  await sendConfirmationEmail(message.orderId);
});

// CP system (consistency-first):
// on a network cut, the minority node refuses to write
if (!canReachMajority()) throw new Error('Unavailable: consistency cannot be guaranteed');

// AP system (availability-first):
// on a network cut, the node responds anyway, with its local data
if (!canReachMajority()) return localData; // potentially stale

// AP variant with eventual consistency:
// the node accepts the write locally then syncs it later
writeLocally(data); scheduleSync(data); // deferred reconciliation

const db = new DatabaseClient(); // created outside the handler, reused across "warm" invocations
export async function handler(event) {
  const { userId } = JSON.parse(event.body);
  const user = await db.user.findUnique({ where: { id: userId } });
  return {
    statusCode: 200,
    body: JSON.stringify(user),
  };
}
